 for bid,r,sign in [(a,ra,-1),(b,rb,1)]:
  if inv_mass[bid]==0:continue
  torque=P if r is None else np.cross(r,P)
  if r is not None:vel[bid-1,:3]=vel[bid-1,:3]+f(sign)*(inv_mass[bid]*P)
  vel[bid-1,3:]=vel[bid-1,3:]+f(sign)*imul(bid,torque,convex)
for op in ops:
