def kpoint(a,b,ra,rb):
 columns=[]
 for e in np.eye(3,dtype=np.float32):columns.append(np.cross(ra,mv(inertia[a],np.cross(e,ra)))+np.cross(rb,mv(inertia[b],np.cross(e,rb))))
