 x[ii]=new;rows.append(dict(label=label,error=float(max(abs(new-actual[ii])/(1+np.maximum(abs(new),abs(actual[ii]))))),projection=info))
rel=lambda a,b:abs(a-b)/(1+np.maximum(abs(a),abs(b)));ie=float(max(rel(x,actual)));ve=float(max(rel(vel.reshape(-1),actualv)));result=dict(status='native-prediction-pass' if max(ie,ve)<=2e-5 else 'native-prediction-failed',maximum_relative_impulse_error=ie,maximum_relative_velocity_error=ve,ranked_blocks=sorted(rows,key=lambda r:r['error'],reverse=True),scope='Free-running CPU float32 row/update replay with exact captured inputs; spring biases and Jacobians from corrected mixed-precision model. Not bitwise whole-shader certification.')
